import useToastService from '@/hooks/useToastService'
import useAgentsStore from '@/stores/agents'
import useChatStore from '@/stores/chat'
import bus from 'vue3-eventbus'
import Loading from '@/components/loading/Loading.vue'
import TabView from 'primevue/tabview'
import TabPanel from 'primevue/tabpanel'

const router = useRouter()
const toast = useToastService()
const agentsStore = useAgentsStore()
const chatStore = useChatStore()
const confirm = useConfirm()

// 获取base URL
const baseUrl = import.meta.env.BASE_URL

// 预设的头像路径列表
const DEFAULT_AVATAR_PATHS = [`${baseUrl}icons/icon/ai-technology (1).png`, `${baseUrl}icons/icon/ai-technology (2).png`]

// 默认头像
const DEFAULT_AVATAR = DEFAULT_AVATAR_PATHS[0]

// 预设的分类选项
const AGENT_CATEGORIES = [
  { label: '开发', value: 'development' },
  { label: '娱乐', value: 'entertainment' },
  { label: '营销', value: 'marketing' },
  { label: '教育', value: 'education' },
  { label: '文化', value: 'culture' },
  { label: '工具', value: 'tools' },
  { label: '写作', value: 'writing' },
  { label: '职业', value: 'job' },
  { label: '心理', value: 'mental_health' },
  { label: '其他', value: 'normal' }
]

// 智能体列表
const agentList = ref([])
const loading = ref(false)

// 对话框控制
const showCreateDialog = ref(false)
const showEditDialog = ref(false)
const showPreviewDialog = ref(false)
const previewAgent = ref(null)

// 当前选中的智能体
const currentAgent = ref(null)
const selectedAvatar = ref(DEFAULT_AVATAR)
const previewEnabled = ref(true)
const generatedWelcomeMessage = ref('')
const generatedQuestions = ref([])

// 创建表单
const createForm = reactive({
  name: '',
  prompt: '',
  description: '',
  welcome_message: '',
  recommended_questions: [],
  category: [],
  avatar: DEFAULT_AVATAR
})

// 编辑表单
const editForm = reactive({
  id: '',
  name: '',
  prompt: '',
  description: '',
  welcome_message: '',
  recommended_questions: [],
  category: [],
  avatar: DEFAULT_AVATAR
})

// 表单错误状态
const formErrors = reactive({
  name: '',
  prompt: ''
})

// 添加一些常用的智能体提示词模板
/* const promptTemplates = [
  {
    label: '通用助手',
    value:
      '你是一个友好、乐于助人的AI助手。你会提供清晰、有用的回答，帮助用户解决各种问题。你的回答应该客观、准确，并且尽可能地考虑用户的意图和需求。'
  },
  {
    label: '编程专家',
    value:
      '你是一个专业的编程助手，擅长解决编程和软件开发的相关问题。你应该提供详细的代码示例、解决方案和最佳实践建议。当涉及到代码问题时，你应该尽量考虑代码的性能、安全性和可维护性。'
  },
  {
    label: '数据分析师',
    value:
      '你是一个专注于数据分析的助手，能够帮助用户理解数据、进行数据处理和分析，以及可视化数据结果。你应该能够解释统计概念，推荐合适的数据分析方法，并提供数据分析的实用建议。'
  }
] */

// 添加菜单相关的响应式变量
const menu = ref()
const activeAgent = ref(null)

// 添加菜单项配置
const menuItems = computed(() => [
  {
    label: '开始对话',
    icon: 'pi pi-comments',
    command: () => {
      if (activeAgent.value) {
        createConversationWithAgent(activeAgent.value)
      }
    }
  },
  {
    label: activeAgent.value?.is_favorite ? '取消收藏' : '收藏',
    icon: activeAgent.value?.is_favorite ? 'pi pi-star-fill' : 'pi pi-star',
    command: () => {
      if (activeAgent.value) {
        toggleFavorite(activeAgent.value)
      }
    }
  },
  {
    label: '编辑',
    icon: 'pi pi-pencil',
    command: () => {
      if (activeAgent.value) {
        openEditDialog(activeAgent.value)
      }
    }
  },
  {
    label: '删除',
    icon: 'pi pi-trash',
    class: 'text-red-600',
    command: () => {
      if (activeAgent.value) {
        deleteAgent(activeAgent.value)
      }
    }
  }
])

// 添加显示菜单的方法
function toggleMenu(event, agent) {
  activeAgent.value = agent

  // 显示菜单
  menu.value.toggle(event)
}

// 验证名称
function validateName(form) {
  if (!form.name) {
    formErrors.name = '请输入智能体名称'
    return false
  }
  if (form.name.length > 60) {
    formErrors.name = '名称不能超过60个字符'
    return false
  }
  formErrors.name = ''
  return true
}

// 验证提示词
function validatePrompt(form) {
  if (!form.prompt) {
    formErrors.prompt = '请输入智能体提示词'
    return false
  }
  if (form.prompt.length < 20) {
    formErrors.prompt = '提示词至少需要20个字符'
    return false
  }
  formErrors.prompt = ''
  return true
}

// 选择提示词模板
/* function selectPromptTemplate(template, isEdit = false) {
  if (isEdit) {
    editForm.prompt = template.value
    validatePrompt(editForm)
  } else {
    createForm.prompt = template.value
    validatePrompt(createForm)
  }
} */

// 选择头像
function selectAvatar(avatar, isEdit = false) {
  if (isEdit) {
    editForm.avatar = avatar
  } else {
    createForm.avatar = avatar
  }
  updatePreview(isEdit)
}

// 更新预览
function updatePreview(isEdit = false) {
  const form = isEdit ? editForm : createForm
  generateWelcomeMessage(form)
  generateRecommendedQuestions(form)
}

// 生成欢迎语预览
function generateWelcomeMessage(form) {
  const name = form.name || '智能体'
  const category = Array.isArray(form.category) && form.category.length > 0 ? form.category[0] : 'normal'

  // 简单模拟后端的欢迎语生成逻辑
  const templates = {
    development: `您好！我是${name}，一名开发助手。我可以帮助您解决编程问题、代码审查和技术选型。请告诉我您需要什么帮助？`,
    marketing: `您好！我是${name}，专注于营销策略的助手。我可以协助您制定营销计划、分析市场趋势和优化转化。有什么我可以帮您的？`,
    education: `您好！我是${name}，您的学习顾问。我可以帮助您理解复杂概念、制定学习计划和提高学习效率。有什么我可以为您讲解的？`,
    culture: `您好！我是${name}，文化领域的助手。我对历史、艺术和文学有深入了解，可以为您提供相关知识和见解。`,
    tools: `您好！我是${name}，您的工具助手。我可以帮助您解决各种实用问题，提供操作指导和建议。`,
    writing: `您好！我是${name}，写作助手。我可以帮助您构思创意、润色文章和改进表达。您需要什么样的写作帮助？`,
    job: `您好！我是${name}。我可以为您提供专业领域的帮助。`,
    entertainment: `您好！我是${name}，娱乐领域的助手。我可以陪您做一些小游戏。`,
    normal: `您好！我是${name}。我可以回答您的问题，提供信息和建议。请随时向我提问。`
  }

  generatedWelcomeMessage.value = templates[category] || templates['normal']
}

// 生成推荐问题预览
function generateRecommendedQuestions(form) {
  // 修改：暂时注释掉按类别加载推荐问题，默认只使用normal中的推荐问题
  // TODO: 如需恢复按类别加载，取消下面两行注释，并注释掉最后一行
  // const category = form.category || 'normal'

  // 简单模拟后端的推荐问题生成逻辑
  const questionSets = {
    development: ['如何优化代码性能？', '有哪些常用的设计模式？', '能帮我解决什么类型的编程问题？'],
    marketing: ['如何提高内容的转化率？', '有哪些有效的社交媒体营销策略？', '怎样分析营销数据以做出决策？'],
    education: ['如何提高学习效率？', '有什么好的记忆方法？', '怎样制定有效的学习计划？'],
    culture: ['能推荐一些经典文学作品吗？', '中国传统文化有哪些特点？', '如何欣赏不同类型的艺术？'],
    tools: ['如何提高工作效率？', '有哪些实用的生活小技巧？', '推荐一些日常实用的工具和应用？'],
    writing: ['如何克服写作障碍？', '有哪些提升写作风格的技巧？', '如何写出引人入胜的开头？'],
    job: ['如何准备面试？', '有哪些职业发展的建议？', '如何提升职场技能？'],
    entertainment: ['能推荐一些好看的电影吗？', '有哪些有趣的游戏推荐？', '最近有什么值得关注的娱乐新闻？'],
    normal: ['你能做什么？', '你有哪些功能？', '如何更有效地使用你的服务？']
  }

  // TODO: 如需恢复按类别加载，取消下面一行注释，并注释掉最后一行
  // generatedQuestions.value = questionSets[category] || questionSets['normal']

  // 修改：强制使用normal分类的推荐问题
  generatedQuestions.value = questionSets['normal']
}

// 标签页控制
const activeTab = ref(0)
// 分类后的智能体列表
const myAgents = ref([])
const featuredAgents = ref([])
const allAgents = computed(() => [...myAgents.value, ...featuredAgents.value])

// 添加新的响应式变量
const searchQuery = ref('')
const selectedCategory = ref('my')

// 过滤后的智能体列表
const filteredAgents = computed(() => {
  return allAgents.value.filter((agent) => {
    // 搜索（匹配名称或描述）
    const searchMatch =
      !searchQuery.value ||
      agent.name.toLowerCase().includes(searchQuery.value.toLowerCase()) ||
      (agent.description && agent.description.toLowerCase().includes(searchQuery.value.toLowerCase()))

    // 如果有搜索关键词，则忽略分类过滤
    if (searchQuery.value) {
      return searchMatch
    }

    // 无搜索关键词时，应用分类过滤
    let categoryMatch = false

    // 处理"收藏"分类
    if (selectedCategory.value === 'favorite') {
      categoryMatch = !!agent.is_favorite
    }
    // 处理"我的"分类
    else if (selectedCategory.value === 'my') {
      categoryMatch = agent.creator_id === 'user'
    } else {
      // 其他分类 - 修改为支持多分类
      // category已经是数组,直接使用
      const agentCategories = agent.category || []
      categoryMatch = selectedCategory.value === 'all' || agentCategories.includes(selectedCategory.value)
    }

    return categoryMatch
  })
})

// 重置过滤器
function resetFilters() {
  searchQuery.value = ''
  selectedCategory.value = 'all'
}

// 加载智能体列表
async function loadAgentList() {
  loading.value = true
  try {
    const response = await agentsStore.fetchAgentList()
    if (response && response.flag === true) {
      const allAgentsData = response.resData || []

      // 确保所有智能体都有is_favorite字段（如果后端没有提供）
      allAgentsData.forEach((agent) => {
        if (agent.is_favorite === undefined) {
          agent.is_favorite = false
        }
      })

      // 根据creator_id分类
      myAgents.value = allAgentsData.filter((agent) => agent.creator_id === 'user')
      featuredAgents.value = allAgentsData.filter((agent) => agent.creator_id !== 'user')
    } else {
      throw new Error(response?.errMsg || '获取智能体列表失败')
    }
  } catch (error) {
    console.error('获取智能体列表失败:', error)
    toast.add({
      severity: 'error',
      summary: '加载失败',
      detail: error.message || '获取智能体列表失败',
      life: 3000
    })
    myAgents.value = []
    featuredAgents.value = []
  } finally {
    loading.value = false
  }
}

// 打开创建对话框
function openCreateDialog() {
  // 重置表单
  createForm.name = ''
  createForm.prompt = ''
  createForm.description = ''
  createForm.welcome_message = ''
  createForm.recommended_questions = []
  createForm.category = []
  createForm.avatar = DEFAULT_AVATAR
  formErrors.name = ''
  formErrors.prompt = ''
  showCreateDialog.value = true
  // 初始化预览
  updatePreview(false)
}

// 打开编辑对话框
function openEditDialog(agent) {
  currentAgent.value = agent
  // 填充表单
  editForm.id = agent.id
  editForm.name = agent.name
  editForm.prompt = agent.prompt
  editForm.description = agent.description || ''
  editForm.welcome_message = agent.welcome_message || ''
  editForm.recommended_questions = agent.recommended_questions || []
  editForm.category = agent.category || ['normal']
  editForm.avatar = agent.avatar || DEFAULT_AVATAR
  formErrors.name = ''
  formErrors.prompt = ''
  showEditDialog.value = true
  // 初始化预览
  updatePreview(true)
}

// 创建智能体
async function createAgent() {
  // 表单验证
  const nameValid = validateName(createForm)
  const promptValid = validatePrompt(createForm)

  if (!nameValid || !promptValid) {
    return
  }

  loading.value = true
  try {
    // 准备数据
    const agentData = {
      name: createForm.name,
      prompt: createForm.prompt,
      description: createForm.description,
      welcome_message: createForm.welcome_message,
      recommended_questions: createForm.recommended_questions || [],
      category: createForm.category,
      avatar: createForm.avatar,
      creator_id: 'user' // 默认值，实际上后端会从header中获取
    }

    // 调用创建接口
    const response = await agentsStore.createAgent(agentData)
    if (response && response.flag === true) {
      toast.add({
        severity: 'success',
        summary: '创建成功',
        detail: '智能体创建成功',
        life: 3000
      })

      // 重新加载列表
      await loadAgentList()

      // 关闭对话框
      showCreateDialog.value = false
    } else {
      throw new Error(response?.errMsg || '创建智能体失败')
    }
  } catch (error) {
    console.error('创建智能体失败:', error)
    toast.add({
      severity: 'error',
      summary: '创建失败',
      detail: error.errMsg || error.message || '创建智能体失败，请重试',
      life: 3000
    })
  } finally {
    loading.value = false
  }
}

// 更新智能体
async function updateAgent() {
  // 表单验证
  const nameValid = validateName(editForm)
  const promptValid = validatePrompt(editForm)

  if (!nameValid || !promptValid) {
    return
  }

  loading.value = true
  try {
    // 准备更新数据
    const updateData = {
      name: editForm.name,
      prompt: editForm.prompt,
      description: editForm.description,
      welcome_message: editForm.welcome_message,
      recommended_questions: editForm.recommended_questions,
      category: editForm.category,
      avatar: editForm.avatar
    }

    // 调用更新接口
    await agentsStore.updateAgent(editForm.id, updateData)
    toast.add({
      severity: 'success',
      summary: '更新成功',
      detail: '智能体更新成功',
      life: 3000
    })

    // 重新加载列表
    await loadAgentList()

    // 关闭对话框
    showEditDialog.value = false
  } catch (error) {
    console.error('更新智能体失败:', error)
    toast.add({
      severity: 'error',
      summary: '更新失败',
      detail: error.message,
      life: 3000
    })
  } finally {
    loading.value = false
  }
}

// 删除智能体
async function deleteAgent(agent) {
  confirm.require({
    message: `确定要删除智能体 "${agent.name}" 吗？此操作不可恢复。`,
    header: '删除确认',
    icon: 'pi pi-exclamation-triangle',
    acceptClass: 'p-button-danger',
    accept: async () => {
      loading.value = true
      try {
        await agentsStore.deleteAgent(agent.id)
        toast.add({
          severity: 'success',
          summary: '删除成功',
          detail: '智能体已成功删除',
          life: 3000
        })

        // 重新加载列表
        await loadAgentList()
      } catch (error) {
        console.error('删除智能体失败:', error)
        toast.add({
          severity: 'error',
          summary: '删除失败',
          detail: error.message,
          life: 3000
        })
      } finally {
        loading.value = false
      }
    }
  })
}

// 创建智能体会话
async function createConversationWithAgent(agent) {
  loading.value = true
  try {
    // 创建新会话
    const session = await chatStore.addConversation()

    if (session && session.id) {
      // 设置会话的智能体
      console.log('尝试设置会话的智能体...')
      await agentsStore.setAssistant(session.id, agent.id)
      console.log('智能体设置成功')

      // 更新会话名称为智能体名称
      console.log('尝试更新会话名称...')
      await chatStore.editConversationName(session.id, agent.name)
      console.log('会话名称更新成功')

      // 设置为当前会话
      chatStore.currentConversationId = session.id
      bus.emit('conversation:created', { type: 'agent' })

      // 发送事件通知聊天页面切换会话
      bus.emit('conversation:change', session.id)

      // 跳转到聊天页面
      router.push({ name: 'chat' })

      toast.add({
        severity: 'success',
        summary: '创建成功',
        detail: '已创建新的智能体会话',
        life: 3000
      })
    } else {
      throw new Error('创建会话失败')
    }
  } catch (error) {
    console.error('创建智能体会话失败:', error)
    toast.add({
      severity: 'error',
      summary: '创建失败',
      detail: error.message,
      life: 3000
    })
  } finally {
    loading.value = false
  }
}

// 格式化推荐问题
function formatRecommendedQuestions(questions) {
  if (!questions) return []

  if (typeof questions === 'string') {
    try {
      return JSON.parse(questions)
    } catch (e) {
      return []
    }
  }

  return questions
}

// 修复头像显示
function getAvatarUrl(avatar) {
  if (!avatar) return DEFAULT_AVATAR
  if (avatar.startsWith('data:') || avatar.startsWith('http')) return avatar
  if (avatar.startsWith(baseUrl)) return avatar
  return `${baseUrl}${avatar.replace(/^\//, '')}`
}

// 切换收藏状态
async function toggleFavorite(agent) {
  try {
    // 记录操作前的状态，用于显示操作类型
    const beforeStatus = !!agent.is_favorite
    const actionType = beforeStatus ? '取消收藏' : '收藏'

    // 调用API更新服务器状态
    const result = await agentsStore.toggleFavorite(agent.id)

    if (result) {
      // 重新加载整个智能体列表，确保状态完全与后端一致
      await loadAgentList()

      // 显示操作成功的消息
      toast.add({
        severity: 'success',
        summary: actionType === '收藏' ? '已收藏' : '已取消收藏',
        detail: actionType === '收藏' ? '智能体已添加到收藏列表' : '智能体已从收藏列表移除',
        life: 3000
      })
    } else {
      toast.add({
        severity: 'error',
        summary: '操作失败',
        detail: `${actionType}操作失败，请稍后重试`,
        life: 3000
      })
    }
  } catch (error) {
    console.error('更改收藏状态失败:', error)
    toast.add({
      severity: 'error',
      summary: '操作失败',
      detail: '更改收藏状态失败',
      life: 3000
    })
  }
}

// 打开预览对话框
function openPreviewDialog(agent) {
  previewAgent.value = agent
  showPreviewDialog.value = true
}

// 关闭预览对话框
function closePreviewDialog() {
  showPreviewDialog.value = false
  previewAgent.value = null
}

// 初始化
onMounted(async () => {
  // 加载智能体列表
  await loadAgentList()

  // 初始化选中的分类
  // 如果URL参数中有category，则使用该值
  const urlParams = new URLSearchParams(window.location.search)
  const categoryParam = urlParams.get('category')
  if (categoryParam) {
    selectedCategory.value = categoryParam
  }
})
</script>

<template>
  <div class="agent-container p-4 md:p-6">
    <div class="header-section flex flex-col md:flex-row md:items-center md:justify-between mb-6">
      <div class="title-container mb-3 md:mb-0">
        <h1 class="text-2xl font-bold mb-1">智能体</h1>
        <p class="text-gray-600">创建和管理您的智能体，让AI助手更好地为您服务</p>
      </div>

      <div class="search-container">
        <div class="search-box">
          <i class="pi pi-search search-icon"></i>
          <InputText v-model="searchQuery" placeholder="搜索智能体" class="search-input" />
